// Family Planner HSBC + NAB balances ingest (balance-only). Mirrors
// app/n8n/bank-ingest.code-node.js (ingestBalancesDir + validateBalance). Reads
// the mounted scrape folders via fs off the always-present Schedule item, so a
// quiet poll cannot short-circuit the chain before the sentinel. Each
// <slug>.balance.json already matches the writeBalance shape; we validate before
// passing it on. Emits one item per valid balance, OR one { _sentinel:true }
// when there are none. KEEP IN SYNC with bank-ingest.code-node.js.
//
// MOUNT: assumes C:\BankScrapes\hsbc -> /data/bankscrapes/hsbc and
// C:\BankScrapes\nab -> /data/bankscrapes/nab.
const fs = require('fs');
const path = require('path');
const ROOTS = ['/data/bankscrapes/hsbc', '/data/bankscrapes/nab'];
const CATS = ['banking', 'super', 'investment'];

function validateBalance(o) {
  if (!o || typeof o !== 'object') return false;
  if (typeof o.accountSlug !== 'string' || !o.accountSlug.length) return false;
  if (typeof o.balance !== 'number' || !Number.isFinite(o.balance)) return false;
  if (typeof o.asOf !== 'string' || !o.asOf.length || Number.isNaN(Date.parse(o.asOf))) return false;
  if (typeof o.institution !== 'string' || !o.institution.length) return false;
  if (!CATS.includes(o.category)) return false;
  return true;
}
const KEEP_DAYS = 14; // each daily scrape covers ~38 days of history, so folders older than this add no new rows
const STALE_CUTOFF = new Date(Date.now() - KEEP_DAYS * 864e5);
const isStaleDir = nm => /^\d{4}-\d{2}-\d{2}$/.test(nm) && new Date(nm) < STALE_CUTOFF;
function listBal(dir, acc) {
  let entries; try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return acc; }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) { if (!isStaleDir(e.name)) listBal(full, acc); }
    else if (/\.balance\.json$/i.test(e.name)) acc.push(full);
  }
  return acc;
}

const out = [];
for (const root of ROOTS) {
  for (const file of listBal(root, [])) {
    let rec; try { rec = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { continue; }
    if (!validateBalance(rec)) continue;
    out.push({ json: { _sentinel: false, _slug: rec.accountSlug, record: rec } });
  }
}
if (out.length === 0) return [{ json: { _sentinel: true } }];
return out;
